import { tileBounds } from "./tiles/bounds.js";
import { renderTile } from "./tiles/render.js";

const EMPTY = Buffer.alloc(0);

export async function handleTile(z: number, x: number, y: number): Promise<Buffer> {
  const bounds = tileBounds(z, x, y);
  if (!bounds) return EMPTY;
  return renderTile(bounds);
}

