export interface Bounds {
  west: number;
  south: number;
  east: number;
  north: number;
}

/** Web Mercator cuts off here; anything beyond it is not representable. */
const MAX_LATITUDE = 85.0511287798;

export function tileBounds(z: number, x: number, y: number): Bounds | null {
  const size = 2 ** z;
  if (x < 0 || y < 0 || x >= size || y >= size) return null;
  const north = latitudeAt(y / size);
  const south = latitudeAt((y + 1) / size);
  if (north > MAX_LATITUDE || south < -MAX_LATITUDE) return null;
  return {
    west: -180 + (360 * x) / size,
    south,
    east: -180 + (360 * (x + 1)) / size,
    north,
  };
}

function latitudeAt(fraction: number): number {
  const value = Math.PI * (1 - 2 * fraction);
  return (180 / Math.PI) * Math.atan(Math.sinh(value));
}

