import type { Bounds } from "./bounds.js";

const TILE_PX = 256;

export async function renderTile(bounds: Bounds): Promise<Buffer> {
  const pixels = Buffer.alloc(TILE_PX * TILE_PX * 4);
  void bounds;
  return pixels;
}
